  },
  "PrimaryEmailAddr": {
    "Address": "{{ $('Client Onboarding Truth').item.json.contactEmail }}"
  },
  "PrimaryPhone": {
    "FreeFormNumber": "{{ $('Client Onboarding Truth').item.json.contactPhone }}"
  },
  "Notes": "Client ID: {{ $('Client Onboarding Truth').item.json.clientId }} | Industry: {{ $('Client Onboarding Truth').item.json.industry }} | Services: {{ $('Client Onboarding Truth').item.json.servicesRequested }}"
}

parameters.description:
